package in.artisanconnect.repo;
import in.artisanconnect.domain.PurchaseOrder; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.*;
public interface OrderRepository extends JpaRepository<PurchaseOrder,Long>{ List<PurchaseOrder> findByCustomerIdOrderByCreatedAtDesc(Long id); @org.springframework.data.jpa.repository.EntityGraph(attributePaths={"items","items.product","items.artisan","customer"}) List<PurchaseOrder> findDistinctByItemsArtisanIdOrderByCreatedAtDesc(Long id); Optional<PurchaseOrder> findByProviderOrderId(String providerOrderId); @org.springframework.data.jpa.repository.Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @Query("select o from PurchaseOrder o where o.id=:id") Optional<PurchaseOrder> lockById(@Param("id") Long id); @org.springframework.data.jpa.repository.Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @Query("select o from PurchaseOrder o where o.providerOrderId=:providerOrderId") Optional<PurchaseOrder> lockByProviderOrderId(@Param("providerOrderId") String providerOrderId); @Query("select distinct o from PurchaseOrder o join fetch o.customer left join fetch o.items i left join fetch i.product left join fetch i.artisan where o.id=:id") Optional<PurchaseOrder> findDetailedById(@Param("id") Long id); }
